def best_skips(costs, budget):
    count, used = 0, 0
    for c in sorted(costs):
        if used + c > budget:
            break
        used += c
        count += 1
    return count


def checkpoint_times(n=80, seconds=480, every=20):
    marks = list(range(every, n + 1, every))
    if not marks or marks[-1] != n:
        marks.append(n)
    return [seconds * k / n for k in marks]
